import {MESSAGE_CATALOG,messageCase,messageCard,messageClue} from './message-content.mjs';
const PLACES=['post','loft'],PAGES=['inspect','revise','play','human','story'],READING=['unknown','self','together'],SUPPORT=['help','audio','example'];
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
const clone=x=>structuredClone(x);
const newSupport=()=>({help:false,audio:false,example:false});
const supportValid=x=>keys(x,SUPPORT)&&SUPPORT.every(k=>typeof x[k]==='boolean');
const mergeSupport=(...items)=>Object.fromEntries(SUPPORT.map(k=>[k,items.some(x=>x?.[k]===true)]));
const contextValid=x=>keys(x,['familiar','priorSupport','priorReading'])&&typeof x.familiar==='boolean'&&supportValid(x.priorSupport)&&Array.isArray(x.priorReading)&&x.priorReading.length<=2&&new Set(x.priorReading).size===x.priorReading.length&&x.priorReading.every(k=>['self','together'].includes(k));
const selectionValid=(c,x)=>keys(x,['cardId','clueId'])&&(x.cardId===null||!!messageCard(c,x.cardId))&&(x.clueId===null||!!messageClue(c,x.clueId));
const attemptValid=(c,a)=>keys(a,['cardId','clueId','reading','support','context'])&&selectionValid(c,{cardId:a.cardId,clueId:a.clueId})&&a.cardId!==null&&READING.includes(a.reading)&&supportValid(a.support)&&contextValid(a.context);
const provenanceValid=p=>p===null||keys(p,['source','reading','support'])&&PLACES.includes(p.source)&&READING.includes(p.reading)&&supportValid(p.support);
function workValid(c,w){return keys(w,['page','clueId','cardId','original','reason','reply','playback','reading','support','feedback','attempts','context','provenance'],['spelling'])&&PAGES.includes(w.page)&&selectionValid(c,{cardId:w.cardId,clueId:w.clueId})&&typeof w.original==='string'&&w.original.length<=600&&['reason','reply'].every(k=>typeof w[k]==='string'&&w[k].length<=400)&&[0,1].includes(w.playback)&&READING.includes(w.reading)&&supportValid(w.support)&&(w.feedback===null||selectionValid(c,w.feedback)&&w.feedback.cardId!==null&&w.feedback.cardId===w.cardId&&w.feedback.clueId===w.clueId)&&Array.isArray(w.attempts)&&w.attempts.length<=24&&w.attempts.every(a=>attemptValid(c,a))&&contextValid(w.context)&&provenanceValid(w.provenance);}
const fresh=()=>({version:1,selected:{post:null,loft:null},cases:{}});
export function messageState(state){
 const r=state.messages;
 if(!keys(r,['version','selected','cases'],['recovered'])||r.version!==1||!keys(r.selected,PLACES)||!object(r.cases)||Object.keys(r.cases).length>MESSAGE_CATALOG.length)return null;
 for(const [id,places] of Object.entries(r.cases)){const c=messageCase(id);if(!c||!object(places)||Object.keys(places).some(p=>!PLACES.includes(p)||!workValid(c,places[p])))return null;}
 if(PLACES.some(p=>r.selected[p]!==null&&(!messageCase(r.selected[p])||!r.cases[r.selected[p]]?.[p])))return null;
 return r;
}
export function ensureMessages(state){if(state.messages===undefined)state.messages=fresh();return messageState(state);}
export function recoverMessages(state){if(messageState(state))return false;const old=state.messages;state.messages=fresh();if(old!==undefined)state.messages.recovered=old;return true;}
const newWork=()=>({page:'inspect',clueId:null,cardId:'original',original:'',reason:'',reply:'',playback:0,reading:'unknown',support:newSupport(),feedback:null,attempts:[],context:{familiar:false,priorSupport:newSupport(),priorReading:[]},provenance:null});
export function currentMessage(state,place){const r=messageState(state);if(!r||!PLACES.includes(place))return null;const c=messageCase(r.selected[place]),work=c&&r.cases[c.id]?.[place];return work?{case:c,work}:null;}
export function chooseMessageCase(state,place,id){if(!PLACES.includes(place)||!messageCase(id))return false;const r=ensureMessages(state);if(!r)return false;r.cases[id]??={};r.cases[id][place]??=newWork();r.selected[place]=id;return true;}
export function setMessagePage(state,place,page){const x=currentMessage(state,place);if(!x||!PAGES.includes(page))return false;x.work.page=page;return true;}
export function setMessageClue(state,place,id){const x=currentMessage(state,place);if(!x||!(id===null||messageClue(x.case,id)))return false;x.work.clueId=id;x.work.feedback=null;return true;}
export function setMessageCard(state,place,id){const x=currentMessage(state,place);if(!x||!(id===null||messageCard(x.case,id)))return false;x.work.cardId=id;x.work.feedback=null;return true;}
export function setMessageText(state,place,field,text){const x=currentMessage(state,place);if(!x||!['original','reason','reply'].includes(field)||typeof text!=='string'||text.length>(field==='original'?600:400))return false;x.work[field]=text;x.work.feedback=null;return true;}
export function setMessageReading(state,place,reading){const x=currentMessage(state,place);if(!x||!READING.includes(reading))return false;const old=x.work.reading;if(old!=='unknown'&&old!==reading&&!x.work.context.priorReading.includes(old))x.work.context.priorReading.push(old);x.work.reading=reading;return true;}
export function useMessageSupport(state,place,kind){const x=currentMessage(state,place);if(!x||!SUPPORT.includes(kind))return false;x.work.support[kind]=true;return true;}
export function setMessagePlayback(state,place,turn){const x=currentMessage(state,place);if(!x||![0,1].includes(turn))return false;x.work.playback=turn;return true;}
function contextFor(r,id,place,w){const other=r.cases[id]?.[place==='post'?'loft':'post'];const context=clone(w.context);if(other){context.familiar=true;context.priorSupport=mergeSupport(context.priorSupport,other.support,other.context.priorSupport,other.provenance?.support);const readings=[...other.context.priorReading,other.reading,...other.attempts.map(a=>a.reading)];for(const reading of readings)if(reading!=='unknown'&&!context.priorReading.includes(reading))context.priorReading.push(reading);}return context;}
export function testMessageCard(state,place){const x=currentMessage(state,place);if(!x)return false;const card=messageCard(x.case,x.work.cardId),clue=messageClue(x.case,x.work.clueId);if(!card)return false;const r=messageState(state);x.work.context=contextFor(r,x.case.id,place,x.work);x.work.attempts.push({cardId:card.id,clueId:clue?.id||null,reading:x.work.reading,support:clone(x.work.support),context:clone(x.work.context)});x.work.attempts=x.work.attempts.slice(-24);x.work.feedback={cardId:card.id,clueId:clue?.id||null};return {card,clue,fits:card.fits,clueRelevant:clue?clue.relevant:null};}
export function carryMessage(state,source){const r=messageState(state),x=currentMessage(state,source);if(!x)return false;const target=source==='post'?'loft':'post',id=x.case.id,reopened=!!r.cases[id][target];if(!reopened){const w=clone(x.work);delete w.spelling;w.page=target==='loft'?'story':'revise';if(target==='loft')w.playback=0;w.feedback=null;w.attempts=[];w.context=contextFor(r,id,source,x.work);w.context.familiar=true;w.context.priorSupport=mergeSupport(w.context.priorSupport,x.work.support);if(x.work.reading!=='unknown'&&!w.context.priorReading.includes(x.work.reading))w.context.priorReading.push(x.work.reading);w.provenance={source,reading:x.work.reading,support:mergeSupport(x.work.support,x.work.context.priorSupport)};r.cases[id][target]=w;}r.selected[target]=id;return {target,reopened};}
